-- Упражнения книги 19, глава 9 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 9, 'la9-addr-brief', 0, 'func', 'Разбор ip -br addr', 'Напишите функцию addr_summary(text): text - вывод ip -br addr (каждая строка: имя интерфейса, состояние и ноль или больше адресов вида адрес/длина, всё через пробелы; в имени может быть суффикс @родитель, например bond0.100@bond0 или veth1@if7 - отбросьте его). Верните словарь с тремя ключами: ipv4 - словарь {имя: список IPv4-адресов в порядке строки} только для интерфейсов, у которых есть хотя бы один IPv4-адрес (адрес IPv4, если в нём есть точка); up_without_ipv4 - имена интерфейсов с состоянием ровно UP, у которых нет IPv4-адреса, в порядке строк; dual_stack - имена интерфейсов, у которых есть IPv4-адрес и есть IPv6-адрес (в нём есть двоеточие), не являющийся link-local (не начинается с fe80:, регистр не важен) и не ::1/128, в порядке строк. Пустые строки пропускайте.', 'def addr_summary(text):
    pass
', 'line.split(): имя, состояние, остальное - адреса; имя режьте по ''@''.', '{"func": "addr_summary", "tests": [{"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0             UP             192.168.1.10/24 fe80::5054:ff:fe12:3456/64 \neth1             UP             fe80::5054:ff:fe12:3457/64 \nvirbr0           DOWN           192.168.122.1/24 \ndocker0          UP             172.17.0.1/16 fe80::42:aff:fe1b:2c3d/64 \n"], "expected": {"ipv4": {"lo": ["127.0.0.1/8"], "eth0": ["192.168.1.10/24"], "virbr0": ["192.168.122.1/24"], "docker0": ["172.17.0.1/16"]}, "up_without_ipv4": ["eth1"], "dual_stack": []}}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth2             LOWERLAYERDOWN \nbond0            UP             10.1.1.5/24 2001:db8:1::5/64 fe80::a00:27ff:fe4e:66a1/64 \nbond0.100@bond0  UP             10.1.100.5/24 \nveth9f3a1b2@if7  UP             \ntun0             UNKNOWN        10.8.0.2/24 \nbr-ex@if3        UP             fe80::1/64 \n"], "expected": {"ipv4": {"lo": ["127.0.0.1/8"], "bond0": ["10.1.1.5/24"], "bond0.100": ["10.1.100.5/24"], "tun0": ["10.8.0.2/24"]}, "up_without_ipv4": ["veth9f3a1b2", "br-ex"], "dual_stack": ["bond0"]}}, {"args": [""], "expected": {"ipv4": {}, "up_without_ipv4": [], "dual_stack": []}}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \n"], "expected": {"ipv4": {"lo": ["127.0.0.1/8"]}, "up_without_ipv4": [], "dual_stack": []}}, {"args": ["eth0             UP             192.168.1.10/24 192.168.1.11/24 2001:db8::10/64 \neth1             UP             10.0.0.1/30 FE80::1/64 \nwlan0            DORMANT        192.168.43.2/24 \ndummy0           UP             \n\n"], "expected": {"ipv4": {"eth0": ["192.168.1.10/24", "192.168.1.11/24"], "eth1": ["10.0.0.1/30"], "wlan0": ["192.168.43.2/24"]}, "up_without_ipv4": ["dummy0"], "dual_stack": ["eth0"]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 9, 'la9-default-gateways', 1, 'func', 'Шлюзы из ip -j route', 'Напишите функцию default_gateways(text): text - вывод ip -j route (JSON-массив объектов маршрутов с полями dst, gateway, dev, metric, flags и другими). Верните список кортежей (gateway, dev, metric) для всех пригодных шлюзов по умолчанию, отсортированный по metric по возрастанию (при равных metric - в порядке появления). Маршрут - шлюз по умолчанию, если его dst равен "default" или "0.0.0.0/0" и его тип (поле type, по умолчанию "unicast") равен "unicast". Если поля metric нет, metric равен 0; если нет gateway, используйте пустую строку. У маршрута может быть список nexthops (элементы с полями gateway, dev, flags): тогда каждый элемент даёт отдельный кортеж с metric самого маршрута, иначе кортеж даёт сам маршрут. Пропускайте вариант (маршрут или элемент nexthops), у которого в списке flags есть "linkdown" или "dead".', 'def default_gateways(text):
    pass
', 'json.loads(text); hops = r.get(''nexthops'', [r]); sort с ключом по metric устойчив.', '{"func": "default_gateways", "tests": [{"args": ["[{\"dst\":\"default\",\"gateway\":\"192.168.1.1\",\"dev\":\"eth0\",\"protocol\":\"dhcp\",\"prefsrc\":\"192.168.1.10\",\"metric\":100,\"flags\":[]},{\"dst\":\"default\",\"gateway\":\"10.8.0.1\",\"dev\":\"wlan0\",\"protocol\":\"dhcp\",\"prefsrc\":\"10.8.0.7\",\"metric\":600,\"flags\":[]},{\"dst\":\"192.168.1.0/24\",\"dev\":\"eth0\",\"protocol\":\"kernel\",\"scope\":\"link\",\"prefsrc\":\"192.168.1.10\",\"metric\":100,\"flags\":[]}]"], "expected": [{"__tuple__": ["192.168.1.1", "eth0", 100]}, {"__tuple__": ["10.8.0.1", "wlan0", 600]}]}, {"args": ["[{\"dst\":\"default\",\"gateway\":\"192.168.1.1\",\"dev\":\"eth0\",\"protocol\":\"dhcp\",\"prefsrc\":\"192.168.1.10\",\"metric\":100,\"flags\":[\"linkdown\"]},{\"dst\":\"default\",\"gateway\":\"10.8.0.1\",\"dev\":\"wlan0\",\"protocol\":\"dhcp\",\"prefsrc\":\"10.8.0.7\",\"metric\":600,\"flags\":[]},{\"dst\":\"10.0.0.0/8\",\"gateway\":\"10.8.0.254\",\"dev\":\"wlan0\",\"protocol\":\"static\",\"flags\":[]}]"], "expected": [{"__tuple__": ["10.8.0.1", "wlan0", 600]}]}, {"args": ["[{\"dst\":\"default\",\"protocol\":\"static\",\"metric\":20,\"flags\":[],\"nexthops\":[{\"gateway\":\"10.0.1.1\",\"dev\":\"eth1\",\"weight\":1,\"flags\":[]},{\"gateway\":\"10.0.2.1\",\"dev\":\"eth2\",\"weight\":1,\"flags\":[\"linkdown\"]},{\"gateway\":\"10.0.3.1\",\"dev\":\"eth3\",\"weight\":1,\"flags\":[]}]},{\"dst\":\"default\",\"gateway\":\"10.0.9.1\",\"dev\":\"eth9\",\"protocol\":\"boot\",\"metric\":5,\"flags\":[]}]"], "expected": [{"__tuple__": ["10.0.9.1", "eth9", 5]}, {"__tuple__": ["10.0.1.1", "eth1", 20]}, {"__tuple__": ["10.0.3.1", "eth3", 20]}]}, {"args": ["[{\"type\":\"blackhole\",\"dst\":\"default\",\"protocol\":\"static\",\"metric\":1,\"flags\":[]},{\"dst\":\"0.0.0.0/0\",\"gateway\":\"172.16.0.1\",\"dev\":\"ens3\",\"protocol\":\"static\",\"flags\":[]},{\"type\":\"unreachable\",\"dst\":\"default\",\"metric\":2,\"flags\":[]}]"], "expected": [{"__tuple__": ["172.16.0.1", "ens3", 0]}]}, {"args": ["[{\"dst\":\"default\",\"dev\":\"ppp0\",\"scope\":\"link\",\"metric\":50,\"flags\":[]},{\"dst\":\"default\",\"gateway\":\"192.0.2.1\",\"dev\":\"eth0\",\"protocol\":\"static\",\"metric\":50,\"flags\":[\"onlink\"]},{\"dst\":\"10.1.0.0/16\",\"gateway\":\"192.0.2.9\",\"dev\":\"eth0\",\"flags\":[]}]"], "expected": [{"__tuple__": ["", "ppp0", 50]}, {"__tuple__": ["192.0.2.1", "eth0", 50]}]}, {"args": ["[]"], "expected": []}, {"args": ["[{\"dst\":\"default\",\"gateway\":\"10.5.5.1\",\"dev\":\"eth5\",\"protocol\":\"ra\",\"metric\":1024,\"flags\":[\"dead\",\"linkdown\"]}]"], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 9, 'la9-route-lookup', 2, 'func', 'Выбор маршрута: префикс и метрика', 'Напишите функцию route_get(routes_text, dst): имитация ip route get для таблицы main и IPv4-адреса dst. Маршруты - текст в формате ip route: одна строка на маршрут; необязательное первое слово - тип (blackhole, unreachable, prohibit, throw, local, broadcast; без него unicast), затем назначение (подсеть a.b.c.d/n, одиночный адрес a.b.c.d значит /32, слово default значит 0.0.0.0/0), затем пары via, dev, proto, scope, src, metric (ключ и значение) и одиночные флаги (linkdown, onlink). Если metric нет, он равен 0. Маршруты с флагом linkdown игнорируйте (будто net.ipv4.conf.all.ignore_routes_with_linkdown = 1). Среди оставшихся маршрутов, содержащих dst, выбирается тот, у которого длиннее префикс; при равных префиксах - с меньшей metric (одинаковый префикс с одинаковой metric не встречается). Если подходящих маршрутов нет, а также если выбран маршрут типа throw, верните "none". Если выбран blackhole, unreachable или prohibit, верните название типа. Иначе верните строку: dst, затем " via <шлюз>" если via есть, затем " dev <интерфейс>", затем " src <адрес>" если src есть.', 'def route_get(routes_text, dst):
    pass
', 'ipaddress.ip_network(dst, strict=False) понимает и ''10.0.0.5'' (это /32); ключ сравнения (prefixlen, -metric).', '{"func": "route_get", "tests": [{"args": ["default via 192.168.1.1 dev eth0 proto dhcp src 192.168.1.10 metric 100 \ndefault via 10.8.0.1 dev tun0 metric 50\n10.0.0.0/8 via 192.168.1.254 dev eth0 proto static metric 20\n10.1.2.0/24 dev eth1 proto kernel scope link src 10.1.2.5 \n10.1.0.0/16 via 10.1.2.1 dev eth1 metric 5\n10.1.0.0/16 via 192.168.1.253 dev eth0 metric 3\nblackhole 10.9.0.0/16\nunreachable 10.8.0.0/16 metric 7\nprohibit 172.31.0.0/16\n172.16.0.0/12 dev eth2 proto kernel scope link src 172.16.0.2 linkdown\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10 metric 100 \n169.254.0.0/16 dev eth0 scope link metric 1000\n", "8.8.8.8"], "expected": "8.8.8.8 via 10.8.0.1 dev tun0"}, {"args": ["default via 192.168.1.1 dev eth0 proto dhcp src 192.168.1.10 metric 100 \ndefault via 10.8.0.1 dev tun0 metric 50\n10.0.0.0/8 via 192.168.1.254 dev eth0 proto static metric 20\n10.1.2.0/24 dev eth1 proto kernel scope link src 10.1.2.5 \n10.1.0.0/16 via 10.1.2.1 dev eth1 metric 5\n10.1.0.0/16 via 192.168.1.253 dev eth0 metric 3\nblackhole 10.9.0.0/16\nunreachable 10.8.0.0/16 metric 7\nprohibit 172.31.0.0/16\n172.16.0.0/12 dev eth2 proto kernel scope link src 172.16.0.2 linkdown\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10 metric 100 \n169.254.0.0/16 dev eth0 scope link metric 1000\n", "10.1.2.77"], "expected": "10.1.2.77 dev eth1 src 10.1.2.5"}, {"args": ["default via 192.168.1.1 dev eth0 proto dhcp src 192.168.1.10 metric 100 \ndefault via 10.8.0.1 dev tun0 metric 50\n10.0.0.0/8 via 192.168.1.254 dev eth0 proto static metric 20\n10.1.2.0/24 dev eth1 proto kernel scope link src 10.1.2.5 \n10.1.0.0/16 via 10.1.2.1 dev eth1 metric 5\n10.1.0.0/16 via 192.168.1.253 dev eth0 metric 3\nblackhole 10.9.0.0/16\nunreachable 10.8.0.0/16 metric 7\nprohibit 172.31.0.0/16\n172.16.0.0/12 dev eth2 proto kernel scope link src 172.16.0.2 linkdown\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10 metric 100 \n169.254.0.0/16 dev eth0 scope link metric 1000\n", "10.1.9.9"], "expected": "10.1.9.9 via 192.168.1.253 dev eth0"}, {"args": ["default via 192.168.1.1 dev eth0 proto dhcp src 192.168.1.10 metric 100 \ndefault via 10.8.0.1 dev tun0 metric 50\n10.0.0.0/8 via 192.168.1.254 dev eth0 proto static metric 20\n10.1.2.0/24 dev eth1 proto kernel scope link src 10.1.2.5 \n10.1.0.0/16 via 10.1.2.1 dev eth1 metric 5\n10.1.0.0/16 via 192.168.1.253 dev eth0 metric 3\nblackhole 10.9.0.0/16\nunreachable 10.8.0.0/16 metric 7\nprohibit 172.31.0.0/16\n172.16.0.0/12 dev eth2 proto kernel scope link src 172.16.0.2 linkdown\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10 metric 100 \n169.254.0.0/16 dev eth0 scope link metric 1000\n", "10.200.0.1"], "expected": "10.200.0.1 via 192.168.1.254 dev eth0"}, {"args": ["default via 192.168.1.1 dev eth0 proto dhcp src 192.168.1.10 metric 100 \ndefault via 10.8.0.1 dev tun0 metric 50\n10.0.0.0/8 via 192.168.1.254 dev eth0 proto static metric 20\n10.1.2.0/24 dev eth1 proto kernel scope link src 10.1.2.5 \n10.1.0.0/16 via 10.1.2.1 dev eth1 metric 5\n10.1.0.0/16 via 192.168.1.253 dev eth0 metric 3\nblackhole 10.9.0.0/16\nunreachable 10.8.0.0/16 metric 7\nprohibit 172.31.0.0/16\n172.16.0.0/12 dev eth2 proto kernel scope link src 172.16.0.2 linkdown\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10 metric 100 \n169.254.0.0/16 dev eth0 scope link metric 1000\n", "10.9.5.5"], "expected": "blackhole"}, {"args": ["default via 192.168.1.1 dev eth0 proto dhcp src 192.168.1.10 metric 100 \ndefault via 10.8.0.1 dev tun0 metric 50\n10.0.0.0/8 via 192.168.1.254 dev eth0 proto static metric 20\n10.1.2.0/24 dev eth1 proto kernel scope link src 10.1.2.5 \n10.1.0.0/16 via 10.1.2.1 dev eth1 metric 5\n10.1.0.0/16 via 192.168.1.253 dev eth0 metric 3\nblackhole 10.9.0.0/16\nunreachable 10.8.0.0/16 metric 7\nprohibit 172.31.0.0/16\n172.16.0.0/12 dev eth2 proto kernel scope link src 172.16.0.2 linkdown\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10 metric 100 \n169.254.0.0/16 dev eth0 scope link metric 1000\n", "10.8.1.1"], "expected": "unreachable"}, {"args": ["default via 192.168.1.1 dev eth0 proto dhcp src 192.168.1.10 metric 100 \ndefault via 10.8.0.1 dev tun0 metric 50\n10.0.0.0/8 via 192.168.1.254 dev eth0 proto static metric 20\n10.1.2.0/24 dev eth1 proto kernel scope link src 10.1.2.5 \n10.1.0.0/16 via 10.1.2.1 dev eth1 metric 5\n10.1.0.0/16 via 192.168.1.253 dev eth0 metric 3\nblackhole 10.9.0.0/16\nunreachable 10.8.0.0/16 metric 7\nprohibit 172.31.0.0/16\n172.16.0.0/12 dev eth2 proto kernel scope link src 172.16.0.2 linkdown\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10 metric 100 \n169.254.0.0/16 dev eth0 scope link metric 1000\n", "172.31.1.1"], "expected": "prohibit"}, {"args": ["default via 192.168.1.1 dev eth0 proto dhcp src 192.168.1.10 metric 100 \ndefault via 10.8.0.1 dev tun0 metric 50\n10.0.0.0/8 via 192.168.1.254 dev eth0 proto static metric 20\n10.1.2.0/24 dev eth1 proto kernel scope link src 10.1.2.5 \n10.1.0.0/16 via 10.1.2.1 dev eth1 metric 5\n10.1.0.0/16 via 192.168.1.253 dev eth0 metric 3\nblackhole 10.9.0.0/16\nunreachable 10.8.0.0/16 metric 7\nprohibit 172.31.0.0/16\n172.16.0.0/12 dev eth2 proto kernel scope link src 172.16.0.2 linkdown\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10 metric 100 \n169.254.0.0/16 dev eth0 scope link metric 1000\n", "172.16.4.4"], "expected": "172.16.4.4 via 10.8.0.1 dev tun0"}, {"args": ["default via 192.168.1.1 dev eth0 proto dhcp src 192.168.1.10 metric 100 \ndefault via 10.8.0.1 dev tun0 metric 50\n10.0.0.0/8 via 192.168.1.254 dev eth0 proto static metric 20\n10.1.2.0/24 dev eth1 proto kernel scope link src 10.1.2.5 \n10.1.0.0/16 via 10.1.2.1 dev eth1 metric 5\n10.1.0.0/16 via 192.168.1.253 dev eth0 metric 3\nblackhole 10.9.0.0/16\nunreachable 10.8.0.0/16 metric 7\nprohibit 172.31.0.0/16\n172.16.0.0/12 dev eth2 proto kernel scope link src 172.16.0.2 linkdown\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10 metric 100 \n169.254.0.0/16 dev eth0 scope link metric 1000\n", "192.168.1.55"], "expected": "192.168.1.55 dev eth0 src 192.168.1.10"}, {"args": ["default via 192.168.1.1 dev eth0 proto dhcp src 192.168.1.10 metric 100 \ndefault via 10.8.0.1 dev tun0 metric 50\n10.0.0.0/8 via 192.168.1.254 dev eth0 proto static metric 20\n10.1.2.0/24 dev eth1 proto kernel scope link src 10.1.2.5 \n10.1.0.0/16 via 10.1.2.1 dev eth1 metric 5\n10.1.0.0/16 via 192.168.1.253 dev eth0 metric 3\nblackhole 10.9.0.0/16\nunreachable 10.8.0.0/16 metric 7\nprohibit 172.31.0.0/16\n172.16.0.0/12 dev eth2 proto kernel scope link src 172.16.0.2 linkdown\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10 metric 100 \n169.254.0.0/16 dev eth0 scope link metric 1000\n", "169.254.1.1"], "expected": "169.254.1.1 dev eth0"}, {"args": ["10.0.0.0/24 dev eth0 proto kernel scope link src 10.0.0.2\n10.0.0.77 via 10.0.0.1 dev eth0\nthrow 10.5.0.0/16\n10.0.0.0/8 via 10.0.0.1 dev eth0 metric 10\n", "10.0.0.77"], "expected": "10.0.0.77 via 10.0.0.1 dev eth0"}, {"args": ["10.0.0.0/24 dev eth0 proto kernel scope link src 10.0.0.2\n10.0.0.77 via 10.0.0.1 dev eth0\nthrow 10.5.0.0/16\n10.0.0.0/8 via 10.0.0.1 dev eth0 metric 10\n", "10.5.1.1"], "expected": "none"}, {"args": ["10.0.0.0/24 dev eth0 proto kernel scope link src 10.0.0.2\n10.0.0.77 via 10.0.0.1 dev eth0\nthrow 10.5.0.0/16\n10.0.0.0/8 via 10.0.0.1 dev eth0 metric 10\n", "10.0.0.5"], "expected": "10.0.0.5 dev eth0 src 10.0.0.2"}, {"args": ["10.0.0.0/24 dev eth0 proto kernel scope link src 10.0.0.2\n10.0.0.77 via 10.0.0.1 dev eth0\nthrow 10.5.0.0/16\n10.0.0.0/8 via 10.0.0.1 dev eth0 metric 10\n", "8.8.8.8"], "expected": "none"}, {"args": ["default dev ppp0 scope link\ndefault via 192.0.2.1 dev eth0 onlink metric 100\ndefault via 192.0.2.2 dev eth1 metric 100\n", "1.1.1.1"], "expected": "1.1.1.1 dev ppp0"}, {"args": ["", "10.0.0.1"], "expected": "none"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 9, 'la9-policy-lookup', 3, 'func', 'Политика маршрутизации: ip rule', 'Напишите функцию policy_lookup(rules_text, tables, packet): имитация поиска маршрута с правилами. rules_text - вывод ip rule: строки вида "100:<TAB>from 10.0.1.10 lookup isp1" (приоритет, двоеточие, табуляция, затем селекторы и действие через пробелы). Селекторы: from <all|префикс> (одиночный адрес значит /32), to <all|префикс>, iif <имя>, fwmark <значение>[/<маска>] (числа в десятичном или 0x-виде; без маски маска 0xffffffff; совпадает, если mark & маска == значение & маска). Действие: lookup <таблица> или одно из слов blackhole, unreachable, prohibit. Строки могут идти в любом порядке: просматривайте правила по возрастанию приоритета. tables - словарь {имя или номер таблицы строкой: текст маршрутов}; отсутствующая таблица пуста. Маршруты - текст в формате ip route: одна строка на маршрут; необязательное первое слово - тип (blackhole, unreachable, prohibit, throw, local, broadcast; без него unicast), затем назначение (подсеть a.b.c.d/n, одиночный адрес a.b.c.d значит /32, слово default значит 0.0.0.0/0), затем пары via, dev, proto, scope, src, metric (ключ и значение) и одиночные флаги (linkdown, onlink). Если metric нет, он равен 0. packet - словарь с ключами src, dst (IPv4), iif (имя интерфейса, пустая строка для пакета, созданного на этом хосте) и mark (число). Правило с селектором iif lo подходит только пакету с пустым iif; другое имя - только пакету с таким же iif. Для подошедшего правила: если действие - слово, верните (приоритет, слово, ""); иначе найдите в таблице маршрут как в обычном поиске (самый длинный префикс, затем меньшая metric; linkdown здесь не учитывайте). Если маршрута нет или он типа throw, переходите к следующему правилу. Если маршрут типа blackhole, unreachable или prohibit, верните (приоритет, тип, префикс), где префикс - строка вида 10.0.0.0/8 (default записывается 0.0.0.0/0, одиночный адрес - a.b.c.d/32). Иначе верните (приоритет, "table " + имя таблицы из правила, префикс). Если ни одно правило не дало результата, верните (-1, "none", "").', 'def policy_lookup(rules_text, tables, packet):
    pass
