INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 9, 'la9-parse-route-get', 4, 'func', 'Разбор ip route get', 'Напишите функцию parse_route_get(text): text - вывод ip route get (одна запись, возможно на нескольких строках: после основной строки идёт строка со словом cache, флагами в угловых скобках и, для пакета из интерфейса, словом iif с именем; пробелы и переводы строк разделяют слова одинаково) либо одна строка ошибки вида "RTNETLINK answers: <сообщение>". Для ошибки верните словарь с kind "error", полем error и остальными полями по умолчанию; поле error: "no-route" для сообщения Network is unreachable, "blackhole" для Invalid argument, "unreachable" для No route to host, "prohibit" для Permission denied, для любого другого сообщения - само сообщение. Иначе запись начинается с необязательного слова local или broadcast (тип), затем идёт адрес назначения; дальше ключи from, via, dev, src, iif и uid, за каждым - одно значение (uid - целое); прочие слова пропускайте. Верните словарь с ключами kind, dst, from, via, dev, src, iif, uid, error. Значения по умолчанию - пустая строка, а uid - -1. kind: "local" или "broadcast" по первому слову, иначе "gateway" если есть via, иначе "direct".', 'def parse_route_get(text):
    pass
', 'text.split() и проход по словам с индексом; ключи, которым нужно значение, пропускайте на два слова.', '{"func": "parse_route_get", "tests": [{"args": ["8.8.8.8 via 192.168.1.1 dev eth0 src 192.168.1.10 uid 1000 \n    cache \n"], "expected": {"kind": "gateway", "dst": "8.8.8.8", "from": "", "via": "192.168.1.1", "dev": "eth0", "src": "192.168.1.10", "iif": "", "uid": 1000, "error": ""}}, {"args": ["192.168.1.55 dev eth0 src 192.168.1.10 uid 1000 \n    cache \n"], "expected": {"kind": "direct", "dst": "192.168.1.55", "from": "", "via": "", "dev": "eth0", "src": "192.168.1.10", "iif": "", "uid": 1000, "error": ""}}, {"args": ["local 127.0.0.1 dev lo src 127.0.0.1 uid 1000 \n    cache <local> \n"], "expected": {"kind": "local", "dst": "127.0.0.1", "from": "", "via": "", "dev": "lo", "src": "127.0.0.1", "iif": "", "uid": 1000, "error": ""}}, {"args": ["broadcast 192.168.1.255 dev eth0 src 192.168.1.10 uid 0 \n    cache <local,brd> \n"], "expected": {"kind": "broadcast", "dst": "192.168.1.255", "from": "", "via": "", "dev": "eth0", "src": "192.168.1.10", "iif": "", "uid": 0, "error": ""}}, {"args": ["RTNETLINK answers: Network is unreachable\n"], "expected": {"kind": "error", "dst": "", "from": "", "via": "", "dev": "", "src": "", "iif": "", "uid": -1, "error": "no-route"}}, {"args": ["RTNETLINK answers: Invalid argument\n"], "expected": {"kind": "error", "dst": "", "from": "", "via": "", "dev": "", "src": "", "iif": "", "uid": -1, "error": "blackhole"}}, {"args": ["RTNETLINK answers: No route to host\n"], "expected": {"kind": "error", "dst": "", "from": "", "via": "", "dev": "", "src": "", "iif": "", "uid": -1, "error": "unreachable"}}, {"args": ["RTNETLINK answers: Permission denied\n"], "expected": {"kind": "error", "dst": "", "from": "", "via": "", "dev": "", "src": "", "iif": "", "uid": -1, "error": "prohibit"}}, {"args": ["8.8.8.8 from 10.0.2.10 via 10.0.2.1 dev eth2 uid 0 \n    cache iif eth1 \n"], "expected": {"kind": "gateway", "dst": "8.8.8.8", "from": "10.0.2.10", "via": "10.0.2.1", "dev": "eth2", "src": "", "iif": "eth1", "uid": 0, "error": ""}}, {"args": ["RTNETLINK answers: Operation not supported\n"], "expected": {"kind": "error", "dst": "", "from": "", "via": "", "dev": "", "src": "", "iif": "", "uid": -1, "error": "Operation not supported"}}, {"args": ["1.1.1.1 via 10.8.0.1 dev tun0 table 100 src 10.8.0.2 uid 0 \n    cache \n"], "expected": {"kind": "gateway", "dst": "1.1.1.1", "from": "", "via": "10.8.0.1", "dev": "tun0", "src": "10.8.0.2", "iif": "", "uid": 0, "error": ""}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 9, 'la9-neigh-report', 5, 'func', 'Отчёт по ip neigh', 'Напишите функцию neigh_report(text): text - вывод ip neigh: строки вида "192.168.1.1 dev eth0 lladdr 52:54:00:12:35:02 REACHABLE"; после lladdr и адреса может стоять слово router; у записей без ответа адреса нет ("192.168.1.77 dev eth0  FAILED"); последнее слово строки - состояние. Пустые строки пропускайте. Верните словарь: states - {состояние: число записей}; unresolved - адреса записей в состоянии FAILED или INCOMPLETE; routers - адреса записей со словом router; shared_mac - {mac: список IPv4-адресов} для каждого MAC (приводите к нижнему регистру), который встречается у двух или более разных IPv4-адресов (адреса с двоеточием в этот словарь не входят). Все списки адресов отсортируйте: сначала IPv4, потом IPv6, внутри - по числовому значению адреса.', 'def neigh_report(text):
    pass
', 'ipaddress.ip_address(a) сравнивается только внутри одной версии; ключ сортировки (ip.version, int(ip)).', '{"func": "neigh_report", "tests": [{"args": ["192.168.1.1 dev eth0 lladdr 52:54:00:12:35:02 REACHABLE\n192.168.1.20 dev eth0 lladdr 08:00:27:aa:bb:cc STALE\n192.168.1.21 dev eth0 lladdr 08:00:27:aa:bb:cc DELAY\n192.168.1.77 dev eth0  FAILED\n192.168.1.88 dev eth0  INCOMPLETE\nfe80::5054:ff:fe12:3502 dev eth0 lladdr 52:54:00:12:35:02 router STALE\n10.0.0.9 dev eth1 lladdr 52:54:00:99:99:99 PERMANENT\n"], "expected": {"states": {"REACHABLE": 1, "STALE": 2, "DELAY": 1, "FAILED": 1, "INCOMPLETE": 1, "PERMANENT": 1}, "unresolved": ["192.168.1.77", "192.168.1.88"], "routers": ["fe80::5054:ff:fe12:3502"], "shared_mac": {"08:00:27:aa:bb:cc": ["192.168.1.20", "192.168.1.21"]}}}, {"args": ["\n192.168.1.10 dev eth0 lladdr 08:00:27:AA:BB:CC REACHABLE\n192.168.1.9 dev eth0 lladdr 08:00:27:aa:bb:cc STALE\n192.168.1.100 dev eth0 lladdr 08:00:27:aa:bb:cc PROBE\n10.1.1.1 dev eth1 lladdr 52:54:00:00:00:01 REACHABLE\n10.1.1.2 dev eth1 lladdr 52:54:00:00:00:02 REACHABLE\n2001:db8::1 dev eth0 lladdr 08:00:27:aa:bb:cc router REACHABLE\n2001:db8::2 dev eth0  FAILED\nfe80::1 dev eth0 lladdr 08:00:27:aa:bb:cc router STALE\n"], "expected": {"states": {"REACHABLE": 4, "STALE": 2, "PROBE": 1, "FAILED": 1}, "unresolved": ["2001:db8::2"], "routers": ["2001:db8::1", "fe80::1"], "shared_mac": {"08:00:27:aa:bb:cc": ["192.168.1.9", "192.168.1.10", "192.168.1.100"]}}}, {"args": [""], "expected": {"states": {}, "unresolved": [], "routers": [], "shared_mac": {}}}, {"args": ["10.0.0.5 dev eth0 lladdr 52:54:00:00:00:05 REACHABLE\n10.0.0.6 dev eth0 lladdr 52:54:00:00:00:06 REACHABLE\n"], "expected": {"states": {"REACHABLE": 2}, "unresolved": [], "routers": [], "shared_mac": {}}}, {"args": ["172.16.0.3 dev bond0  FAILED\n172.16.0.1 dev bond0  FAILED\n172.16.0.2 dev bond0  INCOMPLETE\n2001:db8::7 dev bond0  INCOMPLETE\n2001:db8::3 dev bond0  FAILED\n172.16.0.4 dev bond0 lladdr 02:42:ac:10:00:04 STALE\n172.16.0.8 dev bond0 lladdr 02:42:ac:10:00:04 extern_learn NOARP\n"], "expected": {"states": {"FAILED": 3, "INCOMPLETE": 2, "STALE": 1, "NOARP": 1}, "unresolved": ["172.16.0.1", "172.16.0.2", "172.16.0.3", "2001:db8::3", "2001:db8::7"], "routers": [], "shared_mac": {"02:42:ac:10:00:04": ["172.16.0.4", "172.16.0.8"]}}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 9, 'la9-neigh-state', 6, 'func', 'Жизнь записи соседа', 'Модель записи таблицы соседей (упрощённая: без случайности и с фиксированными таймерами). Состояния: REACHABLE, STALE, DELAY, PROBE, FAILED, PERMANENT. Таймеры: запись REACHABLE становится STALE через 30 секунд после последнего подтверждения; запись DELAY становится PROBE через 5 секунд после входа в DELAY; запись PROBE становится FAILED через 3 секунды после входа в PROBE. События: "confirm" (пришёл ответ) переводит любую запись, кроме PERMANENT, в REACHABLE; "use" (отправлен пакет соседу) переводит STALE в DELAY, в остальных состояниях ничего не меняет. Напишите функцию neigh_state(start, events, end): start - начальное состояние в момент 0 (REACHABLE означает, что подтверждение пришло в момент 0, DELAY и PROBE - что вход в состояние был в момент 0), events - список кортежей (момент, событие) по возрастанию моментов в целых секундах, end - момент, на который нужно узнать состояние (не раньше последнего события). Таймер, срок которого наступил в момент t, срабатывает до события в момент t. Верните состояние в момент end.', 'def neigh_state(start, events, end):
    pass
', 'Храните состояние и момент входа в него; функция advance(t) в цикле применяет таймеры, пока они срабатывают.', '{"func": "neigh_state", "tests": [{"args": ["REACHABLE", [], 29], "expected": "REACHABLE"}, {"args": ["REACHABLE", [], 30], "expected": "STALE"}, {"args": ["REACHABLE", [{"__tuple__": [20, "confirm"]}], 49], "expected": "REACHABLE"}, {"args": ["REACHABLE", [{"__tuple__": [20, "confirm"]}], 50], "expected": "STALE"}, {"args": ["REACHABLE", [{"__tuple__": [40, "use"]}], 40], "expected": "DELAY"}, {"args": ["REACHABLE", [{"__tuple__": [31, "use"]}], 35], "expected": "DELAY"}, {"args": ["REACHABLE", [{"__tuple__": [31, "use"]}], 36], "expected": "PROBE"}, {"args": ["REACHABLE", [{"__tuple__": [31, "use"]}], 39], "expected": "FAILED"}, {"args": ["REACHABLE", [{"__tuple__": [31, "use"]}, {"__tuple__": [38, "confirm"]}], 60], "expected": "REACHABLE"}, {"args": ["REACHABLE", [{"__tuple__": [31, "use"]}, {"__tuple__": [38, "confirm"]}], 68], "expected": "STALE"}, {"args": ["STALE", [{"__tuple__": [10, "use"]}], 15], "expected": "PROBE"}, {"args": ["STALE", [{"__tuple__": [0, "use"]}, {"__tuple__": [3, "use"]}], 6], "expected": "PROBE"}, {"args": ["STALE", [], 1000], "expected": "STALE"}, {"args": ["FAILED", [{"__tuple__": [5, "use"]}], 100], "expected": "FAILED"}, {"args": ["FAILED", [{"__tuple__": [5, "confirm"]}], 6], "expected": "REACHABLE"}, {"args": ["PERMANENT", [{"__tuple__": [5, "confirm"]}, {"__tuple__": [100, "use"]}], 1000], "expected": "PERMANENT"}, {"args": ["PROBE", [{"__tuple__": [2, "confirm"]}], 31], "expected": "REACHABLE"}, {"args": ["PROBE", [], 3], "expected": "FAILED"}, {"args": ["DELAY", [], 4], "expected": "DELAY"}, {"args": ["DELAY", [], 8], "expected": "FAILED"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 9, 'la9-exposed-sockets', 7, 'func', 'Открытые наружу сокеты (ss)', 'Напишите функцию exposed_sockets(text): text - вывод ss -tulpn (с заголовком Netid State Recv-Q Send-Q Local Address:Port Peer Address:Port Process или без него). Строка данных: Netid, State, Recv-Q, Send-Q, локальный адрес:порт, удалённый адрес:порт и, возможно, последняя часть с процессами вида users:(("sshd",pid=801,fd=3),("sshd",pid=2,fd=4)) (имя процесса в кавычках может содержать пробелы, поэтому не режьте её по пробелам). Нужны только слушающие сокеты: tcp в состоянии LISTEN и udp в состоянии UNCONN. Из них оставьте принимающие извне: исключите сокеты, локальный адрес которых - петлевой (127.0.0.0/8, ::1 и IPv4 в IPv6-записи вроде ::ffff:127.0.0.1); адрес может быть в квадратных скобках, содержать суффикс %интерфейс (его отбросьте) или быть звёздочкой * (все интерфейсы, не петлевой). Верните отсортированный список без повторов кортежей (протокол, порт как число, имена процессов): имена - уникальные имена из users:(...) по алфавиту через запятую, пустая строка, если колонки процессов нет.', 'def exposed_sockets(text):
    pass
', 'local.rpartition('':'') отделяет порт от адреса с двоеточиями; имена процессов - re.findall(r''\("([^"]*)",pid='', rest).', '{"func": "exposed_sockets", "tests": [{"args": ["Netid State  Recv-Q Send-Q Local Address:Port  Peer Address:PortProcess\nudp   UNCONN 0      0          127.0.0.53%lo:53      0.0.0.0:* users:((\"systemd-resolve\",pid=612,fd=13))\nudp   UNCONN 0      0                0.0.0.0:68      0.0.0.0:* users:((\"dhclient\",pid=702,fd=7))\ntcp   LISTEN 0      4096             0.0.0.0:22      0.0.0.0:* users:((\"sshd\",pid=801,fd=3))\ntcp   LISTEN 0      4096                [::]:22         [::]:* users:((\"sshd\",pid=801,fd=4))\ntcp   LISTEN 0      511          127.0.0.1:6379      0.0.0.0:* users:((\"redis-server\",pid=1020,fd=6))\ntcp   LISTEN 0      4096                 *:9100            *:* users:((\"node_exporter\",pid=900,fd=3))\ntcp   ESTAB  0      0           192.168.1.10:22 192.168.1.50:51342 users:((\"sshd\",pid=2201,fd=4),(\"sshd\",pid=2150,fd=4))\ntcp   LISTEN 0      128               [::1]:631         [::]:* users:((\"cupsd\",pid=640,fd=7))\n"], "expected": [{"__tuple__": ["tcp", 22, "sshd"]}, {"__tuple__": ["tcp", 9100, "node_exporter"]}, {"__tuple__": ["udp", 68, "dhclient"]}]}, {"args": ["Netid State  Recv-Q Send-Q Local Address:Port  Peer Address:PortProcess\ntcp   LISTEN 0      128           10.1.1.5:3306      0.0.0.0:* users:((\"mysqld\",pid=1500,fd=21))\ntcp   LISTEN 0      128    [::ffff:127.0.0.1]:8080            *:* users:((\"java\",pid=1600,fd=40))\ntcp   LISTEN 0      50     [fe80::a00:27ff:fe4e:66a1%eth0]:8443         [::]:*\nudp   UNCONN 0      0                 [::]:5353         [::]:* users:((\"avahi-daemon\",pid=555,fd=14),(\"avahi-daemon: r\",pid=555,fd=12))\nudp   ESTAB  0      0            10.1.1.5:40000    10.1.1.9:53 users:((\"dig\",pid=7,fd=3))\ntcp   LISTEN 0      4096         127.0.0.1:2379      0.0.0.0:*\ntcp   LISTEN 0      32             0.0.0.0:2222      0.0.0.0:* users:((\"Web Content\",pid=1,fd=5))\n"], "expected": [{"__tuple__": ["tcp", 2222, "Web Content"]}, {"__tuple__": ["tcp", 3306, "mysqld"]}, {"__tuple__": ["tcp", 8443, ""]}, {"__tuple__": ["udp", 5353, "avahi-daemon,avahi-daemon: r"]}]}, {"args": ["Netid State  Recv-Q Send-Q Local Address:Port  Peer Address:PortProcess\n"], "expected": []}, {"args": ["tcp   LISTEN 0      4096         0.0.0.0:443        0.0.0.0:*\ntcp   LISTEN 0      4096       127.0.0.1:5432       0.0.0.0:*\nudp   UNCONN 0      0            0.0.0.0:123        0.0.0.0:*\n"], "expected": [{"__tuple__": ["tcp", 443, ""]}, {"__tuple__": ["udp", 123, ""]}]}, {"args": ["Netid State  Recv-Q Send-Q Local Address:Port  Peer Address:PortProcess\ntcp   LISTEN 0      4096                   *:80            *:* users:((\"nginx\",pid=1,fd=6),(\"nginx\",pid=2,fd=6),(\"nginx\",pid=3,fd=6))\ntcp   LISTEN 0      4096             0.0.0.0:80      0.0.0.0:* users:((\"haproxy\",pid=9,fd=6))\ntcp   LISTEN 0      4096                [::]:80         [::]:* users:((\"nginx\",pid=1,fd=7))\ntcp   TIME-WAIT 0      0               10.0.0.1:80  10.0.0.2:5000\n"], "expected": [{"__tuple__": ["tcp", 80, "haproxy"]}, {"__tuple__": ["tcp", 80, "nginx"]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 9, 'la9-route-problems', 8, 'func', 'Проверка таблицы маршрутов', 'Напишите функцию route_problems(text): проверка таблицы main. Маршруты - текст в формате ip route: одна строка на маршрут; необязательное первое слово - тип (blackhole, unreachable, prohibit, throw, local, broadcast; без него unicast), затем назначение (подсеть a.b.c.d/n, одиночный адрес a.b.c.d значит /32, слово default значит 0.0.0.0/0), затем пары via, dev, proto, scope, src, metric (ключ и значение) и одиночные флаги (linkdown, onlink). Если metric нет, он равен 0. Верните отсортированный по алфавиту список уникальных строк-проблем: "no-default" - среди маршрутов типа unicast нет ни одного с префиксом /0; "bad-gateway <назначение> via <шлюз>" - у маршрута типа unicast есть via без флага onlink, а адрес шлюза не лежит ни в одной подсети "прямого" маршрута на том же интерфейсе (прямой - маршрут типа unicast без via и с длиной префикса больше 0; назначение записывается так, как оно написано в строке); "duplicate <префикс> metric <число>" - два или более маршрутов любых типов с одним и тем же префиксом (в виде a.b.c.d/n, default - 0.0.0.0/0) и одной и той же metric.', 'def route_problems(text):
    pass
', 'Разберите строки в словари; для duplicate считайте пары (str(сеть), metric) в словаре; проблемы кладите в set и сортируйте.', '{"func": "route_problems", "tests": [{"args": ["default via 192.168.1.1 dev eth0 proto dhcp src 192.168.1.10 metric 100\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10 metric 100\n10.9.0.0/16 via 192.168.5.1 dev eth0\n"], "expected": ["bad-gateway 10.9.0.0/16 via 192.168.5.1"]}, {"args": ["192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10\n10.0.0.0/8 via 192.168.1.254 dev eth0 metric 10\n"], "expected": ["no-default"]}, {"args": ["default via 192.168.1.1 dev eth0 metric 100\ndefault via 192.168.2.1 dev eth1 metric 100\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10 metric 100\n192.168.2.0/24 dev eth1 proto kernel scope link src 192.168.2.10 metric 100\n"], "expected": ["duplicate 0.0.0.0/0 metric 100"]}, {"args": ["192.0.2.1 dev eth0 scope link\ndefault via 192.0.2.1 dev eth0\n203.0.113.0/24 via 198.51.100.1 dev eth0 onlink\n172.16.0.0/16 via 192.0.2.1 dev eth1\n"], "expected": ["bad-gateway 172.16.0.0/16 via 192.0.2.1"]}, {"args": [""], "expected": ["no-default"]}, {"args": ["default via 10.0.0.1 dev eth0 metric 50\ndefault via 10.0.0.1 dev eth0 metric 60\n10.0.0.0/24 dev eth0 scope link\n10.0.0.0/24 dev eth1 scope link\nblackhole 10.0.0.0/24 metric 10\ndefault dev eth9\n"], "expected": ["duplicate 10.0.0.0/24 metric 0"]}, {"args": ["10.0.0.0/24 dev eth0 scope link\n10.1.0.0/16 via 10.0.1.1 dev eth0\n10.1.0.0/16 via 10.0.0.1 dev eth0\n"], "expected": ["bad-gateway 10.1.0.0/16 via 10.0.1.1", "duplicate 10.1.0.0/16 metric 0", "no-default"]}, {"args": ["default via 192.168.1.1 dev eth0 proto dhcp src 192.168.1.10 metric 100 \ndefault via 10.8.0.1 dev tun0 metric 50\n10.0.0.0/8 via 192.168.1.254 dev eth0 proto static metric 20\n10.1.2.0/24 dev eth1 proto kernel scope link src 10.1.2.5 \n10.1.0.0/16 via 10.1.2.1 dev eth1 metric 5\n10.1.0.0/16 via 192.168.1.253 dev eth0 metric 3\nblackhole 10.9.0.0/16\nunreachable 10.8.0.0/16 metric 7\nprohibit 172.31.0.0/16\n172.16.0.0/12 dev eth2 proto kernel scope link src 172.16.0.2 linkdown\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10 metric 100 \n169.254.0.0/16 dev eth0 scope link metric 1000\n"], "expected": ["bad-gateway default via 10.8.0.1"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 9, 'la9-rp-filter', 9, 'func', 'Решение rp_filter', 'Напишите функцию rp_check(all_val, iface_val, routes_text, iif, src): будет ли принят пакет с адресом отправителя src (IPv4), пришедший на интерфейс iif. Режим проверки обратного пути - большее из all_val и iface_val (значения net.ipv4.conf.all.rp_filter и net.ipv4.conf.<iif>.rp_filter). Режим 0: принять. Иначе найдите маршрут к src в таблице main как при обычном поиске (самый длинный префикс, затем меньшая metric; флаги игнорируйте). Маршруты - текст в формате ip route: одна строка на маршрут; необязательное первое слово - тип (blackhole, unreachable, prohibit, throw, local, broadcast; без него unicast), затем назначение (подсеть a.b.c.d/n, одиночный адрес a.b.c.d значит /32, слово default значит 0.0.0.0/0), затем пары via, dev, proto, scope, src, metric (ключ и значение) и одиночные флаги (linkdown, onlink). Если metric нет, он равен 0. Если маршрута нет или его тип не unicast, пакет отбрасывается. Режим 1 (строгий): принять, только если dev найденного маршрута равен iif. Режим 2 (свободный): принять, раз маршрут найден. Верните "accept" или "drop".', 'def rp_check(all_val, iface_val, routes_text, iif, src):
    pass
', 'mode = max(all_val, iface_val); дальше тот же поиск маршрута, что в route_get, но по адресу отправителя.', '{"func": "rp_check", "tests": [{"args": [0, 0, "default via 192.168.1.1 dev eth0 metric 100\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10\n10.0.2.0/24 dev eth1 proto kernel scope link src 10.0.2.10\n10.20.0.0/16 via 10.0.2.1 dev eth1\nblackhole 10.99.0.0/16\n", "eth0", "8.8.8.8"], "expected": "accept"}, {"args": [1, 0, "default via 192.168.1.1 dev eth0 metric 100\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10\n10.0.2.0/24 dev eth1 proto kernel scope link src 10.0.2.10\n10.20.0.0/16 via 10.0.2.1 dev eth1\nblackhole 10.99.0.0/16\n", "eth0", "192.168.1.55"], "expected": "accept"}, {"args": [1, 0, "default via 192.168.1.1 dev eth0 metric 100\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10\n10.0.2.0/24 dev eth1 proto kernel scope link src 10.0.2.10\n10.20.0.0/16 via 10.0.2.1 dev eth1\nblackhole 10.99.0.0/16\n", "eth1", "192.168.1.55"], "expected": "drop"}, {"args": [0, 1, "default via 192.168.1.1 dev eth0 metric 100\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10\n10.0.2.0/24 dev eth1 proto kernel scope link src 10.0.2.10\n10.20.0.0/16 via 10.0.2.1 dev eth1\nblackhole 10.99.0.0/16\n", "eth1", "10.20.1.1"], "expected": "accept"}, {"args": [0, 1, "default via 192.168.1.1 dev eth0 metric 100\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10\n10.0.2.0/24 dev eth1 proto kernel scope link src 10.0.2.10\n10.20.0.0/16 via 10.0.2.1 dev eth1\nblackhole 10.99.0.0/16\n", "eth0", "10.20.1.1"], "expected": "drop"}, {"args": [2, 0, "default via 192.168.1.1 dev eth0 metric 100\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10\n10.0.2.0/24 dev eth1 proto kernel scope link src 10.0.2.10\n10.20.0.0/16 via 10.0.2.1 dev eth1\nblackhole 10.99.0.0/16\n", "eth0", "10.20.1.1"], "expected": "accept"}, {"args": [2, 1, "default via 192.168.1.1 dev eth0 metric 100\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10\n10.0.2.0/24 dev eth1 proto kernel scope link src 10.0.2.10\n10.20.0.0/16 via 10.0.2.1 dev eth1\nblackhole 10.99.0.0/16\n", "eth0", "8.8.8.8"], "expected": "accept"}, {"args": [0, 1, "default via 192.168.1.1 dev eth0 metric 100\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10\n10.0.2.0/24 dev eth1 proto kernel scope link src 10.0.2.10\n10.20.0.0/16 via 10.0.2.1 dev eth1\nblackhole 10.99.0.0/16\n", "eth1", "10.99.1.1"], "expected": "drop"}, {"args": [2, 0, "default via 192.168.1.1 dev eth0 metric 100\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10\n10.0.2.0/24 dev eth1 proto kernel scope link src 10.0.2.10\n10.20.0.0/16 via 10.0.2.1 dev eth1\nblackhole 10.99.0.0/16\n", "eth1", "10.99.1.1"], "expected": "drop"}, {"args": [1, 1, "default via 192.168.1.1 dev eth0 metric 100\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10\n10.0.2.0/24 dev eth1 proto kernel scope link src 10.0.2.10\n10.20.0.0/16 via 10.0.2.1 dev eth1\nblackhole 10.99.0.0/16\n", "eth1", "10.0.2.77"], "expected": "accept"}, {"args": [1, 0, "default via 192.168.1.1 dev eth0 metric 100\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10\n10.0.2.0/24 dev eth1 proto kernel scope link src 10.0.2.10\n10.20.0.0/16 via 10.0.2.1 dev eth1\nblackhole 10.99.0.0/16\n", "eth0", "10.0.2.77"], "expected": "drop"}, {"args": [2, 2, "10.0.0.0/8 dev eth0\n", "eth0", "8.8.8.8"], "expected": "drop"}]}');
